import{_ as o,I as r,c as s,o as t,a5 as a,b as l,w as n,a as c,J as d,a6 as m}from"./chunks/framework.BmNIwhaK.js";const w=JSON.parse('{"title":"[Patent Whitepaper] Semantic DOM Inference and Vision-Based Web Crawling Selector Self-Healing","description":"Technical whitepaper on autonomously repairing collection selectors by combining Semantic DOM and Vision AI in environments with target website UI redesigns and CSS class obfuscation","frontmatter":{"title":"[Patent Whitepaper] Semantic DOM Inference and Vision-Based Web Crawling Selector Self-Healing","shortTitle":"[No. 04] Crawling Selector Self-Healing","category":"Core Technologies & Patents","sort":2,"description":"Technical whitepaper on autonomously repairing collection selectors by combining Semantic DOM and Vision AI in environments with target website UI redesigns and CSS class obfuscation","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/patents/04-semantic-dom-self-healing"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/patents/04-semantic-dom-self-healing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/patents/04-semantic-dom-self-healing"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/patents/04-semantic-dom-self-healing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/patents/04-semantic-dom-self-healing"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"[Patent Whitepaper] Semantic DOM Inference and Vision-Based Web Crawling Selector Self-Healing | Empasy Docs"}],["meta",{"property":"og:description","content":"Technical whitepaper on autonomously repairing collection selectors by combining Semantic DOM and Vision AI in environments with target website UI redesigns and CSS class obfuscation"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/patents/04-semantic-dom-self-healing"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"[Patent Whitepaper] Semantic DOM Inference and Vision-Based Web Crawling Selector Self-Healing | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Technical whitepaper on autonomously repairing collection selectors by combining Semantic DOM and Vision AI in environments with target website UI redesigns and CSS class obfuscation"}]]},"headers":[],"relativePath":"en/patents/04-semantic-dom-self-healing.md","filePath":"en/patents/04-semantic-dom-self-healing.md","lastUpdated":1795293539000}'),g={name:"en/patents/04-semantic-dom-self-healing.md"};function h(p,e,u,f,y,b){const i=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="semantic-dom-inference-and-vision-based-crawling-selector-self-healing" tabindex="-1">Semantic DOM Inference and Vision-Based Crawling Selector Self-Healing <a class="header-anchor" href="#semantic-dom-inference-and-vision-based-crawling-selector-self-healing" aria-label="Permalink to “Semantic DOM Inference and Vision-Based Crawling Selector Self-Healing”">​</a></h1><blockquote><p><strong>Patent Application Control No.</strong>: No. 04<br><strong>Title of Invention</strong>: System and Method for Web Crawling Selector Self-Healing and Data Extraction Using Semantic DOM Tree Inference and Multimodal Vision<br><strong>Application Management Status</strong>: Filing Preparation (Eligible for Accelerated Examination, Registrability Grade A)<br><strong>Linked Products</strong>: <code>SyncCrawl</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-technical-problem-to-solve" tabindex="-1">1. Technical Problem to Solve <a class="header-anchor" href="#_1-technical-problem-to-solve" aria-label="Permalink to “1. Technical Problem to Solve”">​</a></h2><p>In modern web applications, bundlers such as Webpack and Vite obfuscate CSS class names into random hash strings on every build (e.g., <code>.header_2x8Fq</code>), and responsive layout redesigns frequently alter the DOM structure.</p><p>Conventional rule-based web crawlers rely on static XPath or CSS selectors. As a result, even minor markup changes on a target website cause data extraction to fail, halting the entire crawling pipeline. Recovering from such failures requires crawler engineers to manually inspect the modified webpage DOM, rewrite selectors, and redeploy—leading to high maintenance overhead and data collection gaps.</p>',6)),(t(),l(m,null,{default:n(()=>[d(i,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Render%20target%20crawling%20webpage%22%5D%20--%3E%20B%7B%22Existing%20selector%20extraction%20succeeds%3F%22%7D%0A%20%20%20%20B%20--%20%22Success%22%20--%3E%20C%5B%22Normalize%20and%20ingest%20collected%20data%22%5D%0A%20%20%20%20B%20--%20%22Extraction%20failed%20(DOM%20change%20detected)%22%20--%3E%20D%5B%22Collect%20compressed%20Semantic%20DOM%20tree%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Capture%20rendered%20screenshot%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22Multimodal%20vision-language%20model%20fusion%20inference%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22Synthesize%20new%20selector%20(SelectorSynthesizer)%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22Zero-downtime%20dynamic%20update%20of%20collection%20template%20DB%22%5D%0A%20%20%20%20H%20--%3E%20C%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-core-operating-mechanism" tabindex="-1">2. Core Operating Mechanism <a class="header-anchor" href="#_2-core-operating-mechanism" aria-label="Permalink to “2. Core Operating Mechanism”">​</a></h2><p>As soon as an extraction failure is detected, the invention triggers the following 4-stage self-healing pipeline at runtime.</p><h3 id="stage-1-semantic-dom-tree-compression-and-screen-capture" tabindex="-1">Stage 1: Semantic DOM Tree Compression and Screen Capture <a class="header-anchor" href="#stage-1-semantic-dom-tree-compression-and-screen-capture" aria-label="Permalink to “Stage 1: Semantic DOM Tree Compression and Screen Capture”">​</a></h3><ul><li>Captures a rendered screenshot image of the webpage at the point of full rendering through a browser Chrome DevTools Protocol (CDP) session.</li><li>Simultaneously strips <code>&lt;script&gt;</code>, <code>&lt;style&gt;</code>, comments, and non-visible meta tags from the raw HTML, normalizing only the text nodes and semantic layout containers (<code>&lt;header&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;table&gt;</code>, etc.) that materially affect visual rendering to produce a Semantic DOM tree that reduces token consumption by approximately 85% or more.</li></ul><h3 id="stage-2-dual-modality-fusion-inference" tabindex="-1">Stage 2: Dual-Modality Fusion Inference <a class="header-anchor" href="#stage-2-dual-modality-fusion-inference" aria-label="Permalink to “Stage 2: Dual-Modality Fusion Inference”">​</a></h3><ul><li>Feeds both the normalized Semantic DOM tree text and the rendered screenshot image into a multimodal Vision-Language Model (VLM) simultaneously.</li><li>Fuses visual layout features (text size, emphasis, relative spatial positioning) with the semantic context of the Semantic DOM (product name labels, currency prefixes, etc.) to pinpoint the unique coordinates and identification path of the DOM node rendering the target extraction data within the modified webpage.</li></ul><h3 id="stage-3-robust-new-selector-synthesis" tabindex="-1">Stage 3: Robust New Selector Synthesis <a class="header-anchor" href="#stage-3-robust-new-selector-synthesis" aria-label="Permalink to “Stage 3: Robust New Selector Synthesis”">​</a></h3><ul><li>The selector synthesis module (<code>SelectorSynthesizer</code>) synthesizes resilient multi-layered selectors according to the following rules: <ul><li>Excludes volatile hashed class names (e.g., <code>class=&quot;sc-1a2b3c&quot;</code>).</li><li>Combines parent semantic container nodes with child text regex anchors (e.g., <code>//article[contains(@class, &#39;product&#39;)]//span[matches(text(), &#39;^[0-9,]+ USD$&#39;)]</code>).</li><li>Generates relative paths anchored to unique ID nodes rather than brittle top-level absolute paths.</li></ul></li></ul><h3 id="stage-4-zero-downtime-template-db-update-and-re-extraction" tabindex="-1">Stage 4: Zero-Downtime Template DB Update and Re-Extraction <a class="header-anchor" href="#stage-4-zero-downtime-template-db-update-and-re-extraction" aria-label="Permalink to “Stage 4: Zero-Downtime Template DB Update and Re-Extraction”">​</a></h3><ul><li>Immediately validates the newly synthesized selector against the live page and records it in the collection template metadata repository for the target domain.</li><li>Subsequent scheduled crawling jobs reference the updated selector by default, restoring the pipeline without requiring a process restart.</li></ul><hr><h2 id="_3-differentiation-over-prior-art" tabindex="-1">3. Differentiation Over Prior Art <a class="header-anchor" href="#_3-differentiation-over-prior-art" aria-label="Permalink to “3. Differentiation Over Prior Art”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Comparison Item</th><th style="text-align:left;">Conventional Rule-Based Crawler</th><th style="text-align:left;">Simple LLM Text Analysis</th><th style="text-align:left;">This Patented System (No. 04)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Response to Broken Selector</strong></td><td style="text-align:left;">Manual code modification and redeployment required</td><td style="text-align:left;">High cost from re-ingesting full HTML</td><td style="text-align:left;"><strong>Autonomous recovery via Semantic DOM + Vision fusion</strong></td></tr><tr><td style="text-align:left;"><strong>Token Consumption</strong></td><td style="text-align:left;">None</td><td style="text-align:left;">Very high due to full raw HTML input</td><td style="text-align:left;"><strong>Approx. 85% reduction via non-visible tag compression</strong></td></tr><tr><td style="text-align:left;"><strong>Dynamic Class Obfuscation</strong></td><td style="text-align:left;">Collection halts when class names change</td><td style="text-align:left;">Inference cost incurred on every request</td><td style="text-align:left;"><strong>Persistent selector synthesis anchored by regex</strong></td></tr><tr><td style="text-align:left;"><strong>Pipeline Continuity</strong></td><td style="text-align:left;">Collection halted until developer intervention</td><td style="text-align:left;">Cumulative API call latency</td><td style="text-align:left;"><strong>Zero-downtime template DB hot-swap</strong></td></tr></tbody></table><hr><h2 id="_4-measured-performance-and-codebase-grounding" tabindex="-1">4. Measured Performance and Codebase Grounding <a class="header-anchor" href="#_4-measured-performance-and-codebase-grounding" aria-label="Permalink to “4. Measured Performance and Codebase Grounding”">​</a></h2><p>Measured results on an internal standard testbed (50 domains across e-commerce, financial disclosures, and news sites, simulating 300 layout changes):</p><ul><li><strong>Mean Time to Recovery (MTTR)</strong>: <strong>4.2 seconds on average</strong> from selector mismatch detection to new selector synthesis and DB persistence.</li><li><strong>Autonomous Repair Success Rate</strong>: <strong>99.4% repair success rate</strong> under UI redesign scenarios without additional engineer intervention.</li></ul><h3 id="codebase-implementation-locations-grounding" tabindex="-1">Codebase Implementation Locations (Grounding) <a class="header-anchor" href="#codebase-implementation-locations-grounding" aria-label="Permalink to “Codebase Implementation Locations (Grounding)”">​</a></h3><ul><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/PlaywrightCrawlingService.java</code>: Rendering capture and DOM compression extractor</li><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/LlmAnalyzePageService.java</code>: Dual-modality fusion node identifier</li><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/PlaywrightManifestService.java</code>: Dynamic template metadata update service</li></ul>',20))])}const v=o(g,[["render",h]]);export{w as __pageData,v as default};
